   117→---
   118→
   119→## 4. Artifact Engine Integration
   120→
   121→### 4.1 Artifact Client
   122→
   123→A simple HTTP client that wraps Artifact Engine's API:
   124→
   125→```typescript
   126→// services/artifact-client.ts
   127→import { config } from "../config";
   128→
   129→const ARTIFACT_ENGINE_URL = config.artifactEngineUrl; // http://localhost:3002
   130→
   131→export const artifactClient = {
   132→  // Get registry to discover available domains/locations
   133→  async getLocations(): Promise<LocationRegistry> {
   134→    const res = await fetch(`${ARTIFACT_ENGINE_URL}/registry/locations`);
   135→    const data = await res.json();
   136→    // Registry returns { locations: { "prefix": {...}, ... } }
   137→    return data.locations;
   138→  },
   139→
   140→  // Search for documents by domain/location
   141→  // Adapts our query shape to Artifact Engine's API
   142→  async search(query: ArtifactSearchQuery): Promise<ArtifactSearchResult[]> {
   143→    // Artifact Engine expects plural arrays for domains/locations
   144→    const engineQuery: ArtifactEngineSearchQuery = {
   145→      domains: query.domain ? [query.domain] : undefined,
   146→      locations: query.location ? [query.location] : undefined,
   147→      keywords: query.keywords,
   148→      tags: query.tags,
   149→      topics: query.topics,
   150→      limit: query.limit,
   151→      offset: query.offset,
   152→    };
   153→
   154→    const res = await fetch(`${ARTIFACT_ENGINE_URL}/artifact/search`, {
   155→      method: "POST",
   156→      headers: { "Content-Type": "application/json" },
   157→      body: JSON.stringify(engineQuery),
   158→    });
   159→    const data = await res.json();
   160→    // Artifact Engine returns { results: [...], elimination_trace: {...} }
   161→    return data.results;
   162→  },
   163→
   164→  // Get document content by ID
   165→  async getContent(artifactId: string): Promise<string> {
   166→    const res = await fetch(`${ARTIFACT_ENGINE_URL}/artifact/${artifactId}/content`);
   167→    return res.text();
   168→  },
   169→
   170→  // Get document metadata
   171→  async getMetadata(artifactId: string): Promise<ArtifactMetadata> {
   172→    const res = await fetch(`${ARTIFACT_ENGINE_URL}/artifact/${artifactId}`);
   173→    return res.json();
   174→  },
   175→};
   176→
   177→// Turnstile's query interface (convenience layer)
   178→interface ArtifactSearchQuery {
   179→  domain?: string;           // e.g., "whitepapers" - wrapped to array for engine
   180→  location?: string;         // e.g., "whitepapers/sdb-framework" - wrapped to array
   181→  keywords?: string[];       // filename token matching
   182→  tags?: string[];           // inferred from registry
   183→  topics?: string[];         // inferred from registry
   184→  limit?: number;
   185→  offset?: number;
   186→}
   187→
   188→// Artifact Engine's actual API shape
   189→interface ArtifactEngineSearchQuery {
   190→  domains?: string[];        // plural array
   191→  locations?: string[];      // plural array (was "category" in earlier draft)
   192→  keywords?: string[];
   193→  tags?: string[];
   194→  topics?: string[];
   195→  limit?: number;
   196→  offset?: number;
   197→}
   198→
   199→interface ArtifactSearchResult {
   200→  artifact_id: string;       // matches engine's response
   201→  path: string;
   202→  filename: string;
   203→  domain: string;
   204→  location: string;          // was "category" - now matches engine
   205→  tags: string[];
   206→  topics: string[];
   207→  tokens: string[];
   208→}
   209→
   210→interface ArtifactMetadata {
   211→  artifact_id: string;
   212→  path: string;
   213→  filename: string;
   214→  domain: string;
   215→  location: string;
   216→  tags: string[];
   217→  topics: string[];
   218→  tokens: string[];
   219→  fields: Record<string, string>;
   220→}
   221→
   222→// Registry is keyed by location prefix
   223→type LocationRegistry = Record<string, LocationEntry>;
   224→
   225→interface LocationEntry {
   226→  domain: string;
   227→  tags: string[];
   228→  topics: string[];
   229→  allowed_extensions: string[];
   230→  filename_rules?: {
   231→    token_delimiters: string[];
   232→    case: string;
   233→    patterns: Array<{ name: string; regex: string }>;
   234→  };
   235→}
   236→```
   237→
   238→### 4.2 Scope Discovery
   239→
   240→The West quadrant dropdown is populated from Artifact Engine's registry:
   241→
   242→```typescript
   243→// services/context-assembler.ts
   244→export const getAvailableScopes = async (): Promise<ContextScope[]> => {
   245→  const registry = await artifactClient.getLocations();
   246→
   247→  // Registry is keyed by location prefix, e.g., "whitepapers/sdb-framework"
   248→  // Find all locations in the whitepapers domain
   249→  const whitepaperLocations = Object.entries(registry)
   250→    .filter(([prefix, entry]) => entry.domain === "whitepapers");
   251→
   252→  if (whitepaperLocations.length === 0) return [];
   253→
   254→  const scopes: ContextScope[] = [
   255→    { type: "all", label: "All Whitepapers" }
   256→  ];
   257→
   258→  // Add locations as groups (e.g., "whitepapers/sdb-framework" → "SDB Framework")
   259→  for (const [prefix, entry] of whitepaperLocations) {
   260→    const groupName = prefix.split("/").pop() || prefix;
   261→    scopes.push({
   262→      type: "group",
   263→      groupId: prefix,  // Use full location prefix
   264→      label: inferTitle(groupName),
   265→    });
   266→  }
   267→
   268→  // Add individual documents
   269→  const allDocs = await artifactClient.search({ domain: "whitepapers" });
   270→  for (const doc of allDocs) {
   271→    scopes.push({
   272→      type: "document",
   273→      documentId: doc.artifact_id,  // Use artifact_id from engine
   274→      label: inferTitle(doc.filename),
   275→    });
   276→  }
   277→
   278→  return scopes;
   279→};
   280→
   281→const inferTitle = (filename: string): string => {
   282→  // software_defined_business.md → "Software Defined Business"
   283→  // sdb-framework → "SDB Framework"
   284→  return filename
   285→    .replace(/\.md$/, "")
   286→    .replace(/[_-]/g, " ")
   287→    .replace(/\b\w/g, c => c.toUpperCase());
   288→};
   289→```
   290→
   291→### 4.3 Context Assembly
   292→
   293→The "baby assembler" - fetches documents and concatenates them:
   294→
   295→```typescript
   296→// services/context-assembler.ts
   297→export const assembleContext = async (scope: ContextScope): Promise<AssembledContext> => {
   298→  let artifacts: ArtifactSearchResult[];
   299→
   300→  switch (scope.type) {
   301→    case "all":
   302→      artifacts = await artifactClient.search({ domain: "whitepapers" });
   303→      break;
   304→    case "group":
   305→      artifacts = await artifactClient.search({
   306→        domain: "whitepapers",
   307→        location: scope.groupId  // groupId is the full location prefix
   308→      });
   309→      break;
   310→    case "document":
   311→      artifacts = await artifactClient.search({
   312→        domain: "whitepapers"
   313→      }).then(all => all.filter(a => a.artifact_id === scope.documentId));
   314→      break;
   315→  }
   316→
   317→  // Fetch content for each document
   318→  const documents: AssembledDocument[] = await Promise.all(
   319→    artifacts.map(async (artifact) => ({
   320→      id: artifact.artifact_id,
   321→      title: inferTitle(artifact.filename),
   322→      content: await artifactClient.getContent(artifact.artifact_id),
   323→    }))
   324→  );
   325→
   326→  // Build the context string
   327→  const contextString = documents
   328→    .map(doc => `### ${doc.title}\n\n${doc.content}`)
   329→    .join("\n\n---\n\n");
   330→
   331→  return {
   332→    documents,
   333→    contextString,
   334→    tokenEstimate: Math.ceil(contextString.length / 4), // Rough estimate
   335→  };
   336→};
   337→
   338→interface AssembledContext {
   339→  documents: AssembledDocument[];
   340→  contextString: string;
   341→  tokenEstimate: number;
   342→}
   343→
   344→interface AssembledDocument {
   345→  id: string;
   346→  title: string;
   347→  content: string;
   348→}
   349→```
   350→
