   394→### 5.2 Session
   395→
   396→```typescript
   397→interface Session {
   398→  id: string;
   399→  corpusId: string;
   400→  contextScope: ContextScope;
   401→  personaId: string;
   402→  title: string;
   403→  mode: SessionMode;
   404→  cards: TurnCard[];
   405→  createdAt: string;
   406→  updatedAt: string;
   407→
   408→  // Distillation (updated periodically)
   409→  distillation?: SessionDistillation;
   410→}
   411→
   412→type SessionMode = "strict" | "creative" | "analytical" | "writing";
   413→
   414→interface ContextScope {
   415→  type: "all" | "group" | "documents";
   416→  groupId?: string;            // If type === "group"
   417→  documentIds?: string[];      // If type === "documents"
   418→}
   419→
   420→interface SessionDistillation {
   421→  summary: string;
   422→  keyInsights: string[];
   423→  questionsExplored: string[];
   424→  updatedAt: string;
   425→  turnCount: number;           // Turns when last updated
   426→}
   427→
   428→interface TurnCard {
   429→  id: string;
   430→  index: number;
   431→  title: string;
   432→  titleEdited: boolean;
   433→  userContent: string;
   434→  aiContent: string;
   435→  timestamp: string;
   436→  collapsed: boolean;
   437→  tags: string[];
   438→
   439→  // Metadata
   440→  wordCount: number;
   441→  hasCode: boolean;
   442→  documentsReferenced?: string[];  // Which docs were in context
   443→}
   444→```
