### 7.2 Message Types

```typescript
// Client → Server
type ClientMessage =
  | { type: "SUBSCRIBE"; sessionId: string }
  | { type: "UNSUBSCRIBE"; sessionId: string }
  | { type: "PING" };

// Server → Client
type ServerMessage =
  | { type: "PONG" }
  | { type: "SUBSCRIBED"; sessionId: string }
  | { type: "STREAM_START"; cardId: string }
  | { type: "STREAM_CHUNK"; cardId: string; content: string; index: number }
  | { type: "STREAM_END"; cardId: string; card: TurnCard }
  | { type: "STREAM_ERROR"; cardId: string; error: string }
